#include <item/EffectRuntime.hpp>
#include <item/RecoveryRuntime.hpp>
void TimedUtilityCatalogWorker(const GameSqlConfig& player,const std::shared_ptr<const auriga::item::ItemCatalog>& catalog,
    const std::string& password,const std::string& path,const std::vector<BulkSource>& sources)
{
    using namespace auriga::item;CAsyncSQL sql;sql.SetTimeouts(5);sql.SetRetryConnectionErrors(false);Check(sql.Setup("127.0.0.1","root",password.c_str(),"player","utf8mb4",true,player.port),"timed utility private SQL connects");auto& store=runtime::ItemStore::Instance();Check(store.Start(player,catalog,"source-timed-utility-worker").has_value(),"timed utility actual item worker starts");
    for(unsigned n=0;n<sources.size();++n){
        const auto key=sources[n].grant.key;const auto& profile=*TimedItemProfile(*catalog,key);const ItemOwner owner{ItemOwnerKind::Character,65000u+n};const std::array layouts{ItemStorageLayout{{owner,ItemStorageKind::Inventory,1},5,9,4}};
        Check(persistence::ProvisionOwner(sql,*catalog,owner,layouts,{}).has_value(),"timed utility owner provisioned");auto state=persistence::LoadCurrentItemOwner(sql,*catalog,owner).value();unsigned serial=0;bool replay=false;constexpr std::uint64_t now=1794787200000ULL;
        const auto op=[&](){return std::array<std::uint8_t,16>{0xB8,static_cast<std::uint8_t>(n),static_cast<std::uint8_t>(++serial)};};
        const auto submit=[&](const ItemCommit& commit){std::optional<runtime::CommitOutcome> got;Check(runtime::RequestCommit(owner,state.fence.sessionGeneration,commit,[&](auto out){got=std::move(out);}),"timed utility commit queues");for(unsigned spin=0;!got && spin<1000;++spin){store.Drain();std::this_thread::sleep_for(std::chrono::milliseconds(10));}Check(got.has_value(),"timed utility callback completes");return std::move(*got);};
        const auto apply=[&](const ItemCommit& commit){auto got=submit(commit);Check(got.write && got.state,"timed utility write saves and reloads");replay=got.write->replay;state=*got.state;};
        const auto relog=[&](){const auto before=state;const auto generation=persistence::ClaimOwnerSession(sql,*catalog,owner).value();state=persistence::LoadItemOwner(sql,*catalog,owner,generation).value();Check(state.items==before.items && state.recovery==before.recovery,"utility lifetime and exact debit survive a new SQL session");};
        const auto write=[&](const std::string& phase,const char* kind,const auto& bytes){std::ofstream f(path+"."+std::to_string(n)+"."+phase+"."+kind+".hex");for(auto b:bytes){auto v=static_cast<unsigned char>(b);f<<"0123456789abcdef"[v>>4]<<"0123456789abcdef"[v&15];}f<<'\n';Check(f.good(),"timed utility actual packet exported");};
        auto spec=sources[n].grant;spec.count=2;const auto ids=runtime::PeekInstanceIds(1);runtime::SpendInstanceIds(1);apply(MakeGrantCommit(*catalog,op(),state.fence,state.storages,state.items,spec,ids).value());const auto id=ids[0];auto original=state.items[0];
        ItemEffectFacts facts;facts.alive=facts.allowed=true;facts.actor.context=RecoveryContext::World;facts.actor.level=255;facts.actor.pools={1000000,1000000,1000000,1000000};const auto* policy=catalog->FindUsePolicy(catalog->Find(key)->base.usePolicy);while(!(policy->allowedClasses&(1u<<facts.actor.classIndex)))++facts.actor.classIndex;while(!(policy->allowedSexes&(1u<<facts.actor.sexIndex)))++facts.actor.sexIndex;
        const auto timer=[&](std::uint64_t elapsed,bool dead){
            auto plan=PlanRecoveryScheduleTick(*catalog,state.recovery,elapsed,facts.actor,dead,false);
            if(!plan && plan.error()==RecoveryUseError::NoEffect){auto next=AdvanceRecoverySchedule(*catalog,state.recovery,elapsed).value();++next.revision;plan=RecoverySchedulePlan{next};}
            Check(plan.has_value(),"actual runtime timer proposal admits online utility");auto current=facts;current.alive=!dead;NormalizeTimedItems(*catalog,plan->after,now,&current);
            ItemCommit r;r.operationId=op();r.catalogRevision=catalog->Revision();r.catalogHash=catalog->ContentHash();r.kind=ItemOperationKind::Service;r.owners={state.fence};r.outcomeCode=0x2003;r.result={'R','T','M',1};r.recovery=ItemRecoveryChange{owner,state.recovery,plan->after,elapsed};Check(ValidateItemCommit(*catalog,r).has_value(),"actual runtime timer commit validates");return r;
        };
        const auto output=[&](const std::string& phase,std::uint8_t status=1){write(phase,"inventory",EncodeTypedInventory(*catalog,state.storages,state.wallets,state.items).value());write(phase,"details",EncodeTypedItemDetails(*catalog,state.items).value());const auto item=std::ranges::find(state.items,id,&PersistentItem::id);const auto* source=item!=state.items.end() ? &*item : &original;write(phase,"effects",EncodeItemEffectsRuntime(*catalog,{status,255,123,456,source,&state.recovery,state.items,now}).value());};
        output("ready");auto use=MakeItemEffectUse(*catalog,op(),state.fence,state.storages,state.items,state.recovery,id,facts,0,now,100+n).value();apply(use);Check(state.items[0].count==1 && state.recovery.effects.size()==1 && state.recovery.effects[0].remainingMs==profile.durationMs,"source utility item debit and original duration save atomically");const auto active=state;apply(use);Check(replay && state.items==active.items && state.recovery==active.recovery,"use receipt replay cannot extend utility or consume twice");Check(!MakeItemEffectUse(*catalog,op(),state.fence,state.storages,state.items,state.recovery,id,facts,0,now,200+n),"duplicate utility does not consume the remaining unit");Check(CollectItemEffectBonuses(*catalog,state.recovery,state.items).value().empty(),"utility grants no fabricated combat stats");output("active",3);relog();output("relogged",3);
        const auto elapsed=timer(123,false);apply(elapsed);Check(state.recovery.effects[0].remainingMs==profile.durationMs-123,"online utility time persists exactly once");const auto advanced=state;apply(elapsed);Check(replay && state.recovery==advanced.recovery,"timer receipt replay cannot age utility twice");relog();output("elapsed",3);
        const auto died=timer(0,true);apply(died);const bool fish=profile.utility==TimedEffectUtility::FishMind;Check(state.recovery.effects.empty()==fish,"original death policy clears fish mind and retains no-death protection");relog();output("dead",3);
        if(!fish){const auto effect=FindTimedUtility(*catalog,state.recovery,profile.utility,now).value();auto spent=MakeItemEffectCancel(*catalog,op(),state.fence,state.recovery,0,now,state.recovery.generation,effect).value();apply(spent);Check(state.recovery.effects.empty() && state.items[0].count==1,"eligible protection spend removes the exact effect without another inventory debit");const auto gone=state;apply(spent);Check(replay && state.recovery==gone.recovery && state.items==gone.items,"one-shot protection cannot be consumed twice");relog();}
        output("spent",3);
        auto stale=MakeItemEffectUse(*catalog,op(),state.fence,state.storages,state.items,state.recovery,id,facts,0,now,300+n).value();const auto unchanged=state;sql.DirectQuery(("UPDATE player.item_owner_fence SET state_revision=state_revision+1 WHERE owner_kind=1 AND owner_id="+std::to_string(owner.id)).c_str());auto refused=submit(stale);Check(!refused.write && refused.state && refused.state->items==unchanged.items && refused.state->recovery==unchanged.recovery,"stale owner fence rolls back utility and last item debit together");state=*refused.state;output("stale",7);
        original=state.items[0];use=MakeItemEffectUse(*catalog,op(),state.fence,state.storages,state.items,state.recovery,id,facts,0,now,400+n).value();apply(use);Check(state.items.empty() && FindTimedUtility(*catalog,state.recovery,profile.utility,now).has_value(),"last source unit disappears while independent utility persists");const auto last=state;apply(use);Check(replay && state.items.empty() && state.recovery==last.recovery,"last-use replay cannot resurrect a source instance or refresh utility");relog();output("last",3);
        const auto expired=timer(profile.durationMs,false);apply(expired);Check(state.items.empty() && state.recovery.effects.empty(),"full original online lifetime expires without a source object");relog();output("expired",3);apply(use);Check(replay && state.items.empty() && state.recovery.effects.empty(),"old use receipt cannot revive a subsequently expired utility");
    }
    store.Stop();std::cout<<"SOURCE_TIMED_UTILITY_WORKER=SUCCESS sources="<<sources.size()<<" checks="<<checks<<std::endl;
}
